from itertools import combinations
R=set('ABCDEF'); F=[('AB','C'),('C','B'),('A','D'),('D','E'),('AC','F'),('EF','D')]
def cl(X):
    X=set(X); ch=True
    while ch:
        ch=False
        for l,r in F:
            if set(l)<=X and not set(r)<=X: X|=set(r); ch=True
    return X
keys=[]
for n in range(1,7):
    for c in combinations(sorted(R),n):
        if cl(c)==R and not any(set(k)<=set(c) for k in keys): keys.append(c)
prime=set().union(*map(set,keys))
print([''.join(k) for k in keys], sum(1 for l,r in F if not set(r)<=set(l) and cl(l)!=R and not set(r)<=prime))  # ['AB','AC'] 3
